import urllib.request
import urllib.error
import time

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        # For 429: retry up to 3 times with exponential backoff (0.5, 1, 2)
        # For 5xx: retry once after 1s
        # For 4xx (except 429): raise immediately
        # For URLError: retry once after 1s

        # We'll handle retries in a loop with state tracking
        # For 429: max 3 retries (so up to 4 attempts total? Or 3 retries meaning 3 additional attempts?)
        # "retry up to 3 times" means 3 retries, so 4 total attempts
        # For 5xx: retry once, so 2 total attempts
        # For URLError: retry once, so 2 total attempts

        # Let's track attempts per error type
        rate_limit_attempts = 0
        server_error_attempts = 0
        network_error_attempts = 0

        while True:
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                return body
            except urllib.error.HTTPError as e:
                code = e.code
                if code == 429:
                    rate_limit_attempts += 1
                    if rate_limit_attempts <= 3:
                        # Backoff: 0.5, 1, 2
                        backoff = 0.5 * (2 ** (rate_limit_attempts - 1))
                        time.sleep(backoff)
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after {rate_limit_attempts} retries")
                elif 500 <= code <= 599:
                    server_error_attempts += 1
                    if server_error_attempts <= 1:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error {code} after retry")
                elif 400 <= code <= 499:
                    raise ClientError(f"Client error {code}")
                else:
                    # Other HTTP errors, treat as client error or raise
                    raise ClientError(f"HTTP error {code}")
            except urllib.error.URLError as e:
                network_error_attempts += 1
                if network_error_attempts <= 1:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError(f"Network error after retry: {e}")
            except Exception as e:
                raise ConnectionError(f"Unexpected error: {e}")
